import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        testValidTransfers();
        testMalformedOutcomes();
        testSnapshotsAndImmutability();
    }

    private static void testValidTransfers() throws Exception {
        Map<String, String> links = new LinkedHashMap<String, String>();
        links.put("other", "ignored");
        links.put("payment", "https://pay.example/a?x=1&y=2");
        Solution.TransferRequest get = Solution.buildTransfer(new Solution.OperationOutcome(
                new Solution.TransferDirective(Solution.TransferMethod.GET), links));
        same(Solution.TransferMethod.GET, get.getMethod(), "GET method");
        equals("https://pay.example/a?x=1&y=2", get.getDestination(), "destination copied exactly");

        Solution.TransferRequest post = Solution.buildTransfer(new Solution.OperationOutcome(
                new Solution.TransferDirective(Solution.TransferMethod.POST),
                Collections.singletonMap("payment", "opaque:=destination")));
        same(Solution.TransferMethod.POST, post.getMethod(), "POST method");
        equals("opaque:=destination", post.getDestination(), "destination must not be interpreted");
    }

    private static void testMalformedOutcomes() {
        expectPaymentException(new CheckedAction() {
            public void run() throws Exception { Solution.buildTransfer(null); }
        }, "null outcome");
        expectPaymentException(new CheckedAction() {
            public void run() throws Exception {
                Solution.buildTransfer(new Solution.OperationOutcome(null,
                        Collections.singletonMap("payment", "x")));
            }
        }, "null directive");
        expectPaymentException(new CheckedAction() {
            public void run() throws Exception {
                Solution.buildTransfer(new Solution.OperationOutcome(new Solution.TransferDirective(null),
                        Collections.singletonMap("payment", "x")));
            }
        }, "null method");
        expectPaymentException(new CheckedAction() {
            public void run() throws Exception {
                Solution.buildTransfer(new Solution.OperationOutcome(
                        new Solution.TransferDirective(Solution.TransferMethod.GET), null));
            }
        }, "null links");
        expectPaymentExceptionFor(Collections.<String, String>emptyMap(), "missing payment");
        expectPaymentExceptionFor(Collections.singletonMap("Payment", "x"), "case-sensitive key");
        expectPaymentExceptionFor(Collections.singletonMap("payment", (String) null), "null destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", ""), "empty destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", " "), "space-only destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", "a b"), "space in destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", "a\tb"), "tab in destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", "a\nb"), "newline in destination");
        expectPaymentExceptionFor(Collections.singletonMap("payment", "a\rb"), "carriage return in destination");
    }

    private static void testSnapshotsAndImmutability() throws Exception {
        LinkedHashMap<String, String> source = new LinkedHashMap<String, String>();
        source.put("payment", "first");
        Solution.OperationOutcome outcome = new Solution.OperationOutcome(
                new Solution.TransferDirective(Solution.TransferMethod.POST), source);

        source.put("payment", "changed-before-build");
        source.clear();
        equals("first", outcome.getLinks().get("payment"), "outcome snapshots constructor map");

        Map<String, String> exposed = outcome.getLinks();
        try {
            exposed.put("payment", "attempted-mutation");
            exposed.clear();
        } catch (UnsupportedOperationException acceptable) {
            // An unmodifiable view is permitted, but not required.
        }
        equals("first", outcome.getLinks().get("payment"), "getter cannot mutate outcome state");

        Solution.TransferRequest request = Solution.buildTransfer(outcome);
        equals("first", request.getDestination(), "request snapshots destination");
        same(Solution.TransferMethod.POST, request.getMethod(), "request snapshots method");

        Map<String, String> laterView = outcome.getLinks();
        try {
            laterView.put("payment", "later");
        } catch (UnsupportedOperationException acceptable) {
            // Either an unmodifiable map or a detached mutable copy satisfies immutability.
        }
        equals("first", request.getDestination(), "request does not retain outcome map");
        equals("first", Solution.buildTransfer(outcome).getDestination(), "outcome remains unchanged");
    }

    private static void expectPaymentExceptionFor(final Map<String, String> links, String label) {
        expectPaymentException(new CheckedAction() {
            public void run() throws Exception {
                Solution.buildTransfer(new Solution.OperationOutcome(
                        new Solution.TransferDirective(Solution.TransferMethod.GET), links));
            }
        }, label);
    }

    private static void expectPaymentException(CheckedAction action, String label) {
        try {
            action.run();
            throw new AssertionError("Expected PaymentException: " + label);
        } catch (Solution.PaymentException expected) {
            check(expected instanceof Exception, "PaymentException must extend Exception");
        } catch (Exception other) {
            throw new AssertionError("Wrong exception for " + label + ": " + other, other);
        }
    }

    private interface CheckedAction { void run() throws Exception; }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }

    private static void same(Object expected, Object actual, String message) {
        if (expected != actual) throw new AssertionError(message);
    }
}

