import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

public final class Solution {
    public static final class Bundle {
        private final Map<String, Map<String, String>> resources;
        private final List<String> recipes;
        private final Map<String, String> language;

        private Bundle(Map<String, Map<String, String>> resources,
                List<String> recipes, Map<String, String> language) {
            this.resources = resources;
            this.recipes = recipes;
            this.language = language;
        }

        public Map<String, Map<String, String>> getResources() { return resources; }
        public List<String> getRecipes() { return recipes; }
        public Map<String, String> getLanguage() { return language; }
    }

    private Solution() {}

    private static void requireMap(Map<?, ?> map) {
        if (map == null) {
            throw new IllegalArgumentException("null map");
        }
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            if (entry.getKey() == null || entry.getValue() == null) {
                throw new IllegalArgumentException("null map entry");
            }
        }
    }

    public static Bundle prepare(Set<String> enabledModules,
            Map<String, Map<String, String>> resources,
            Map<String, List<String>> recipeDefinitions,
            Map<String, String> clientLanguage, boolean client) {
        if (enabledModules == null) {
            throw new IllegalArgumentException("invalid modules");
        }
        for (String module : enabledModules) {
            if (module == null) {
                throw new IllegalArgumentException("invalid modules");
            }
        }

        requireMap(resources);
        requireMap(recipeDefinitions);
        requireMap(clientLanguage);

        for (Map<String, String> moduleResources : resources.values()) {
            requireMap(moduleResources);
        }
        for (List<String> definitions : recipeDefinitions.values()) {
            if (definitions == null) {
                throw new IllegalArgumentException("invalid recipe list");
            }
            for (String definition : definitions) {
                if (definition == null) {
                    throw new IllegalArgumentException("invalid recipe list");
                }
            }
        }

        Map<String, Map<String, String>> keptResources = new LinkedHashMap<String, Map<String, String>>();
        for (Map.Entry<String, Map<String, String>> entry : resources.entrySet()) {
            if (enabledModules.contains(entry.getKey())) {
                Map<String, String> nestedCopy = new LinkedHashMap<String, String>(entry.getValue());
                keptResources.put(entry.getKey(), Collections.unmodifiableMap(nestedCopy));
            }
        }

        List<String> keptRecipes = new ArrayList<String>();
        for (String module : new TreeSet<String>(enabledModules)) {
            List<String> definitions = recipeDefinitions.get(module);
            if (definitions != null) {
                List<String> sorted = new ArrayList<String>(definitions);
                Collections.sort(sorted);
                keptRecipes.addAll(sorted);
            }
        }

        Map<String, String> language = client
                ? new LinkedHashMap<String, String>(clientLanguage)
                : new LinkedHashMap<String, String>();
        return new Bundle(
                Collections.unmodifiableMap(keptResources),
                Collections.unmodifiableList(keptRecipes),
                Collections.unmodifiableMap(language));
    }
}

