import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class SolutionTest {
    public static void main(String[] args) {
        testFilteringOrderingAndDuplicates();
        testImmutableCollectionInputs();
        testClientLanguageSwitchAndEmptyInputs();
        testDeepCopiesAndUnmodifiableResults();
        testMalformedInputsAreRejectedGlobally();
    }

    private static void testFilteringOrderingAndDuplicates() {
        Set<String> enabled = new LinkedHashSet<String>(Arrays.asList("zeta", "alpha", "missing"));
        LinkedHashMap<String, Map<String, String>> resources = new LinkedHashMap<String, Map<String, String>>();
        resources.put("disabled", linkedMap("d", "no"));
        resources.put("zeta", linkedMap("second", "2", "first", "1"));
        resources.put("alpha", linkedMap("x", "A"));

        LinkedHashMap<String, List<String>> recipes = new LinkedHashMap<String, List<String>>();
        recipes.put("zeta", Arrays.asList("b", "a", "a"));
        recipes.put("disabled", Arrays.asList("0"));
        recipes.put("alpha", Arrays.asList("z", "a"));

        Map<String, String> language = linkedMap("hello", "namaste", "bye", "later");
        Solution.Bundle bundle = Solution.prepare(enabled, resources, recipes, language, true);
        equals(Arrays.asList("zeta", "alpha"), new ArrayList<String>(bundle.getResources().keySet()),
                "outer resource iteration order preserved while filtering");
        equals(Arrays.asList("second", "first"),
                new ArrayList<String>(bundle.getResources().get("zeta").keySet()),
                "nested resource order preserved");
        equals(Arrays.asList("a", "z", "a", "a", "b"), bundle.getRecipes(),
                "recipes sorted by module then recipe with duplicates preserved");
        equals(language, bundle.getLanguage(), "client receives language");
        check(!bundle.getResources().containsKey("disabled"), "disabled resources removed");
    }

    private static void testImmutableCollectionInputs() {
        Solution.Bundle empty = Solution.prepare(Set.<String>of(),
                Map.<String, Map<String, String>>of(), Map.<String, List<String>>of(),
                Map.<String, String>of(), true);
        check(empty.getResources().isEmpty(), "Set.of empty enabled set accepted");
        check(empty.getRecipes().isEmpty(), "empty immutable recipe map accepted");
        check(empty.getLanguage().isEmpty(), "empty immutable language map accepted");

        Map<String, Map<String, String>> resources = Map.<String, Map<String, String>>of(
                "m", Map.of("k", "v"), "disabled", Map.of("x", "y"));
        Map<String, List<String>> recipes = Map.<String, List<String>>of(
                "m", List.of("b", "a", "a"), "empty", List.<String>of(),
                "disabled", List.of("ignored"));
        Solution.Bundle one = Solution.prepare(Set.of("m"), resources, recipes,
                Map.of("language", "value"), true);
        equals(Map.of("m", Map.of("k", "v")), one.getResources(), "Set.of singleton filters resources");
        equals(List.of("a", "a", "b"), one.getRecipes(), "nonempty List.of sorted with duplicates");
        equals(Map.of("language", "value"), one.getLanguage(), "immutable language copied");

        Solution.Bundle enabledEmptyRecipe = Solution.prepare(Set.of("empty"), resources, recipes,
                Map.<String, String>of(), false);
        check(enabledEmptyRecipe.getRecipes().isEmpty(), "enabled empty List.of recipe accepted");
    }

    private static void testClientLanguageSwitchAndEmptyInputs() {
        Map<String, String> language = linkedMap("k", "v");
        Solution.Bundle server = Solution.prepare(Collections.<String>emptySet(),
                Collections.<String, Map<String, String>>emptyMap(),
                Collections.<String, List<String>>emptyMap(), language, false);
        check(server.getResources().isEmpty(), "empty resources valid");
        check(server.getRecipes().isEmpty(), "empty recipes valid");
        check(server.getLanguage().isEmpty(), "server omits language");

        Solution.Bundle client = Solution.prepare(Collections.<String>emptySet(),
                Collections.<String, Map<String, String>>emptyMap(),
                Collections.<String, List<String>>emptyMap(), language, true);
        equals(language, client.getLanguage(), "client language independent of enabled modules");
    }

    private static void testDeepCopiesAndUnmodifiableResults() {
        LinkedHashSet<String> enabled = new LinkedHashSet<String>();
        enabled.add("m");
        LinkedHashMap<String, String> nested = linkedMap("a", "1");
        LinkedHashMap<String, Map<String, String>> resources = new LinkedHashMap<String, Map<String, String>>();
        resources.put("m", nested);
        ArrayList<String> recipeList = new ArrayList<String>(Arrays.asList("r2", "r1"));
        LinkedHashMap<String, List<String>> recipes = new LinkedHashMap<String, List<String>>();
        recipes.put("m", recipeList);
        LinkedHashMap<String, String> language = linkedMap("l", "v");

        Solution.Bundle bundle = Solution.prepare(enabled, resources, recipes, language, true);
        enabled.clear();
        nested.put("a", "changed");
        nested.put("b", "2");
        resources.clear();
        recipeList.clear();
        recipes.clear();
        language.put("l", "changed");

        equals(Collections.singletonMap("a", "1"), bundle.getResources().get("m"), "nested snapshot");
        equals(Arrays.asList("r1", "r2"), bundle.getRecipes(), "recipe snapshot");
        equals(Collections.singletonMap("l", "v"), bundle.getLanguage(), "language snapshot");
        expectUnsupported(new Action() { public void run() { bundle.getResources().clear(); } }, "outer resources");
        expectUnsupported(new Action() {
            public void run() { bundle.getResources().get("m").put("x", "y"); }
        }, "nested resources");
        expectUnsupported(new Action() { public void run() { bundle.getRecipes().add("x"); } }, "recipes");
        expectUnsupported(new Action() { public void run() { bundle.getLanguage().put("x", "y"); } }, "language");
    }

    private static void testMalformedInputsAreRejectedGlobally() {
        final Set<String> enabled = Collections.singleton("m");
        final Map<String, Map<String, String>> resources =
                Collections.<String, Map<String, String>>singletonMap("m", Collections.singletonMap("k", "v"));
        final Map<String, List<String>> recipes =
                Collections.<String, List<String>>singletonMap("m", Collections.singletonList("r"));
        final Map<String, String> language = Collections.singletonMap("l", "v");

        expectIllegal(new Action() { public void run() { Solution.prepare(null, resources, recipes, language, true); } }, "null enabled set");
        expectIllegal(new Action() { public void run() { Solution.prepare(enabled, null, recipes, language, true); } }, "null resources map");
        expectIllegal(new Action() { public void run() { Solution.prepare(enabled, resources, null, language, true); } }, "null recipes map");
        expectIllegal(new Action() { public void run() { Solution.prepare(enabled, resources, recipes, null, false); } }, "null language on server");

        LinkedHashSet<String> badEnabled = new LinkedHashSet<String>();
        badEnabled.add("m"); badEnabled.add(null);
        expectIllegalCall(badEnabled, resources, recipes, language, "null enabled module");

        LinkedHashMap<String, Map<String, String>> badResources = new LinkedHashMap<String, Map<String, String>>();
        badResources.put(null, Collections.singletonMap("k", "v"));
        expectIllegalCall(enabled, badResources, recipes, language, "null resource module key");
        badResources.clear(); badResources.put("disabled", null);
        expectIllegalCall(enabled, badResources, recipes, language, "null disabled resource map");
        LinkedHashMap<String, String> badInner = new LinkedHashMap<String, String>();
        badInner.put(null, "v"); badResources.clear(); badResources.put("disabled", badInner);
        expectIllegalCall(enabled, badResources, recipes, language, "null nested resource key");
        badInner.clear(); badInner.put("k", null);
        expectIllegalCall(enabled, badResources, recipes, language, "null nested resource value");

        LinkedHashMap<String, List<String>> badRecipes = new LinkedHashMap<String, List<String>>();
        badRecipes.put(null, Collections.singletonList("r"));
        expectIllegalCall(enabled, resources, badRecipes, language, "null recipe module key");
        badRecipes.clear(); badRecipes.put("disabled", null);
        expectIllegalCall(enabled, resources, badRecipes, language, "null disabled recipe list");
        badRecipes.clear(); badRecipes.put("disabled", Arrays.asList("r", null));
        expectIllegalCall(enabled, resources, badRecipes, language, "null disabled recipe element");

        LinkedHashMap<String, String> badLanguage = new LinkedHashMap<String, String>();
        badLanguage.put(null, "v");
        expectIllegalCall(enabled, resources, recipes, badLanguage, "null language key");
        badLanguage.clear(); badLanguage.put("x", null);
        expectIllegalCall(enabled, resources, recipes, badLanguage, "null language value on server");
    }

    private static void expectIllegalCall(final Set<String> enabled,
            final Map<String, Map<String, String>> resources,
            final Map<String, List<String>> recipes,
            final Map<String, String> language, String label) {
        expectIllegal(new Action() {
            public void run() { Solution.prepare(enabled, resources, recipes, language, false); }
        }, label);
    }

    private static LinkedHashMap<String, String> linkedMap(String... entries) {
        LinkedHashMap<String, String> result = new LinkedHashMap<String, String>();
        for (int i = 0; i < entries.length; i += 2) result.put(entries[i], entries[i + 1]);
        return result;
    }

    private interface Action { void run(); }

    private static void expectIllegal(Action action, String label) {
        try { action.run(); throw new AssertionError("Expected IllegalArgumentException: " + label); }
        catch (IllegalArgumentException expected) { }
    }

    private static void expectUnsupported(Action action, String label) {
        try { action.run(); throw new AssertionError("Expected unmodifiable " + label); }
        catch (UnsupportedOperationException expected) { }
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }
}

