import unittest
from solution import nearest_bundle


class NearestBundleTests(unittest.TestCase):
    def test_nearest_exact_marker(self):
        entries = {"/work/quartz.mod", "/work/a/quartz.mod", "/work/a/doc.txt"}
        original = set(entries)
        self.assertEqual(nearest_bundle("/work/a/doc.txt", "quartz", entries), "/work/a")
        self.assertEqual(entries, original)

    def test_suffix_markers_and_direct_child_requirement(self):
        entries = {
            "/repo/project.qproj",
            "/repo/a/deeper/ignored.qproj",
            "/repo/a/b/file.txt",
        }
        self.assertEqual(nearest_bundle("/repo/a/b/file.txt", "quartz", entries), "/repo")
        orbit_entries = {"/x/y/app.orb", "/x/y/z/doc.md"}
        self.assertEqual(nearest_bundle("/x/y/z/doc.md", "orbit", orbit_entries), "/x/y")

    def test_root_marker(self):
        self.assertEqual(nearest_bundle("/a/b.txt", "ember", {"/ember.lock"}), "/")
        self.assertEqual(nearest_bundle("/a/b.txt", "orbit", {"/root.orb"}), "/")

    def test_root_entry_is_valid_and_not_itself_a_marker(self):
        entries = {"/", "/a", "/a/ember.lock"}
        original = set(entries)
        self.assertEqual(nearest_bundle("/a/doc", "ember", entries), "/a")
        self.assertEqual(entries, original)
        self.assertEqual(nearest_bundle("/a/doc", "ember", {"/"}), "/a")

    def test_profile_marker_search_precedes_anchor_fallback(self):
        entries = {"/a/.anchor", "/ember.lock", "/a/b/doc.txt"}
        self.assertEqual(nearest_bundle("/a/b/doc.txt", "ember", entries), "/")

    def test_nearest_anchor_when_no_profile_marker(self):
        entries = {"/.anchor", "/a/.anchor", "/a/b/doc.txt"}
        self.assertEqual(nearest_bundle("/a/b/doc.txt", "orbit", entries), "/a")

    def test_falls_back_to_containing_directory(self):
        self.assertEqual(nearest_bundle("/one/two/file.txt", "quartz", set()), "/one/two")
        self.assertEqual(nearest_bundle("/file.txt", "ember", set()), "/")

    def test_wrong_argument_types(self):
        cases = [
            (1, "quartz", set()),
            ("/a.txt", 1, set()),
            ("/a.txt", "quartz", []),
        ]
        for args in cases:
            with self.subTest(args=args):
                with self.assertRaises(TypeError):
                    nearest_bundle(*args)

    def test_unknown_profile_and_malformed_paths(self):
        with self.assertRaises(ValueError):
            nearest_bundle("/a.txt", "unknown", set())
        bad_documents = ("", "relative.txt", "/", "/a/", "/a//b.txt", "/a/./b.txt", "/a/../b.txt")
        for path in bad_documents:
            with self.subTest(path=path):
                with self.assertRaises(ValueError):
                    nearest_bundle(path, "quartz", set())
        bad_entries = (
            {"relative"},
            {"/a//b"},
            {"/a/./b"},
            {"/a/../b"},
            {1},
        )
        for entries in bad_entries:
            with self.subTest(entries=entries):
                with self.assertRaises((TypeError, ValueError)):
                    nearest_bundle("/doc.txt", "quartz", entries)


if __name__ == "__main__":
    unittest.main()

