mod solution;

use solution::{RegistryError, TagRegistry};

#[test]
fn registers_scoped_tags_and_returns_global_lexicographic_order() {
    let mut registry = TagRegistry::new();
    assert!(registry.register_scope("z_scope").is_ok());
    assert!(registry.register_scope("A").is_ok());
    assert!(registry.register_scope("a").is_ok());
    assert!(registry.register_scope("a0").is_ok());
    assert!(registry.register_tag("z_scope", "beta").is_ok());
    assert!(registry.register_tag("A", "tag2").is_ok());
    assert!(registry.register_tag("z_scope", "alpha").is_ok());
    assert!(registry.register_tag("a", "x").is_ok());
    assert!(registry.register_tag("a0", "x").is_ok());
    assert_eq!(
        registry.tags(),
        vec![
            "A::tag2".to_string(),
            "a0::x".to_string(),
            "a::x".to_string(),
            "z_scope::alpha".to_string(),
            "z_scope::beta".to_string(),
        ]
    );
}

#[test]
fn validates_ascii_name_grammar_for_scopes_and_tags() {
    let mut registry = TagRegistry::new();
    for name in ["", "1name", "-name", "has-dash", "has space", "é"] {
        match registry.register_scope(name) {
            Err(RegistryError::InvalidName(value)) => assert_eq!(value, name),
            _ => panic!("invalid scope was not reported correctly"),
        }
    }

    assert!(registry.register_scope("_valid9").is_ok());
    match registry.register_tag("_valid9", "9bad") {
        Err(RegistryError::InvalidName(value)) => assert_eq!(value, "9bad"),
        _ => panic!("invalid tag was not reported correctly"),
    }
    assert!(registry.register_tag("_valid9", "Good_2").is_ok());
}

#[test]
fn reports_unknown_scopes_and_duplicate_identity() {
    let mut registry = TagRegistry::new();
    match registry.register_tag("missing", "tag") {
        Err(RegistryError::UnknownScope(value)) => assert_eq!(value, "missing"),
        _ => panic!("unknown scope not reported"),
    }

    assert!(registry.register_scope("scope").is_ok());
    match registry.register_scope("scope") {
        Err(RegistryError::Duplicate(value)) => assert_eq!(value, "scope"),
        _ => panic!("duplicate scope not reported"),
    }

    assert!(registry.register_tag("scope", "tag").is_ok());
    match registry.register_tag("scope", "tag") {
        Err(RegistryError::Duplicate(value)) => assert_eq!(value, "scope::tag"),
        _ => panic!("duplicate tag not reported"),
    }
}

#[test]
fn disabled_batch_does_not_inspect_or_change_entries() {
    let mut registry = TagRegistry::new();
    assert!(registry.register_scope("scope").is_ok());
    assert!(registry.register_tag("scope", "existing").is_ok());
    let before = registry.tags();
    let entries = [("", ""), ("missing", "9bad"), ("scope", "existing")];
    assert!(registry.register_batch(false, &entries).is_ok());
    assert_eq!(registry.tags(), before);
}

#[test]
fn enabled_batch_is_atomic_on_late_failure() {
    let mut registry = TagRegistry::new();
    assert!(registry.register_scope("scope").is_ok());
    assert!(registry.register_tag("scope", "existing").is_ok());
    let snapshot = registry.clone();
    let entries = [("scope", "first"), ("scope", "existing"), ("scope", "later")];

    match registry.register_batch(true, &entries) {
        Err(RegistryError::Duplicate(value)) => assert_eq!(value, "scope::existing"),
        _ => panic!("expected duplicate"),
    }
    assert_eq!(registry.tags(), snapshot.tags());
}

#[test]
fn duplicates_within_one_batch_also_roll_back_and_empty_batch_succeeds() {
    let mut registry = TagRegistry::new();
    assert!(registry.register_scope("s").is_ok());
    let entries = [("s", "x"), ("s", "x")];
    assert!(matches!(
        registry.register_batch(true, &entries),
        Err(RegistryError::Duplicate(_))
    ));
    assert!(registry.tags().is_empty());
    assert!(registry.register_batch(true, &[]).is_ok());
}

#[test]
fn cloning_and_returned_tag_vectors_are_detached() {
    let mut registry = TagRegistry::new();
    assert!(registry.register_scope("s").is_ok());
    assert!(registry.register_tag("s", "one").is_ok());

    let mut cloned = registry.clone();
    assert!(cloned.register_tag("s", "two").is_ok());
    assert_eq!(registry.tags(), vec!["s::one".to_string()]);
    assert_eq!(
        cloned.tags(),
        vec!["s::one".to_string(), "s::two".to_string()]
    );

    let mut returned = registry.tags();
    returned.clear();
    assert_eq!(registry.tags(), vec!["s::one".to_string()]);
}

