pub fn heaviest_route(
    node_count: usize,
    root: usize,
    edges: &[(usize, usize, i64)],
) -> Option<i64> {
    if node_count == 0 || root >= node_count || edges.len() != node_count - 1 {
        return None;
    }

    let mut children = vec![Vec::<(usize, i64)>::new(); node_count];
    let mut parents = vec![0usize; node_count];
    for &(parent, child, weight) in edges {
        if parent >= node_count || child >= node_count || parent == child {
            return None;
        }
        parents[child] = parents[child].checked_add(1)?;
        if parents[child] > 1 {
            return None;
        }
        children[parent].push((child, weight));
    }

    if parents[root] != 0
        || parents
            .iter()
            .enumerate()
            .any(|(node, &count)| node != root && count != 1)
    {
        return None;
    }

    let mut seen = vec![false; node_count];
    let mut stack = vec![(root, 0i64)];
    let mut best: Option<i64> = None;

    while let Some((node, total)) = stack.pop() {
        if seen[node] {
            return None;
        }
        seen[node] = true;

        if children[node].is_empty() {
            best = Some(best.map_or(total, |current| current.max(total)));
            continue;
        }

        for &(child, weight) in &children[node] {
            let next_total = total.checked_add(weight)?;
            stack.push((child, next_total));
        }
    }

    if seen.iter().all(|&value| value) {
        best
    } else {
        None
    }
}

