#[path = "solution.rs"]
mod solution;

use solution::{analyze_tours, Passage, Tour, TourError};

fn passage(from: &str, to: &str, minutes: u64) -> Passage {
    Passage {
        from: from.to_string(),
        to: to.to_string(),
        minutes,
    }
}

#[test]
fn line_graph_returns_both_orientations_in_lexicographic_order() {
    let passages = vec![passage("B", "C", 7), passage("A", "B", 5)];
    let before = passages.clone();
    let tours = match analyze_tours(&passages) {
        Ok(value) => value,
        Err(_) => panic!("valid passages rejected"),
    };
    assert_eq!(
        tours,
        vec![
            Tour {
                rooms: vec!["A".to_string(), "B".to_string(), "C".to_string()],
                minutes: 12,
            },
            Tour {
                rooms: vec!["C".to_string(), "B".to_string(), "A".to_string()],
                minutes: 12,
            },
        ]
    );
    assert_eq!(passages, before);
}

#[test]
fn complete_three_room_graph_returns_every_oriented_tour_sorted() {
    let passages = vec![
        passage("b", "a", 1),
        passage("c", "a", 2),
        passage("b", "c", 4),
    ];
    let tours = match analyze_tours(&passages) {
        Ok(value) => value,
        Err(_) => panic!("valid passages rejected"),
    };
    let rooms: Vec<Vec<String>> = tours.iter().map(|tour| tour.rooms.clone()).collect();
    assert_eq!(
        rooms,
        vec![
            vec!["a".to_string(), "b".to_string(), "c".to_string()],
            vec!["a".to_string(), "c".to_string(), "b".to_string()],
            vec!["b".to_string(), "a".to_string(), "c".to_string()],
            vec!["b".to_string(), "c".to_string(), "a".to_string()],
            vec!["c".to_string(), "a".to_string(), "b".to_string()],
            vec!["c".to_string(), "b".to_string(), "a".to_string()],
        ]
    );
    assert_eq!(
        tours.iter().map(|tour| tour.minutes).collect::<Vec<_>>(),
        vec![5, 6, 3, 6, 3, 5]
    );
}

#[test]
fn validates_passages_in_input_order() {
    let empty_first = vec![passage("", "x", 1), passage("a", "a", 1)];
    assert_eq!(analyze_tours(&empty_first), Err(TourError::EmptyRoom));

    let self_first = vec![passage("a", "a", 1), passage("", "x", 1)];
    assert_eq!(analyze_tours(&self_first), Err(TourError::SelfPassage));
}

#[test]
fn duplicate_detection_is_undirected_and_names_are_case_sensitive() {
    let duplicate = vec![passage("a", "b", 1), passage("b", "a", 2)];
    assert_eq!(
        analyze_tours(&duplicate),
        Err(TourError::DuplicatePassage)
    );

