fn exact_maximum_tour_cost_is_valid() {
    let passages = vec![passage("a", "b", u64::MAX)];
    let tours = match analyze_tours(&passages) {
        Ok(value) => value,
        Err(_) => panic!("exact maximum tour cost rejected"),
    };
