mod solution;

use solution::{parse_device_spec, ParseDeviceError};

#[test]
fn parses_trimmed_fields_and_preserves_tag_order_and_duplicates() {
    let input = String::from("  dev-_01  , on , alpha : beta-2 : alpha ");
    let before = input.clone();
    let spec = match parse_device_spec(&input) {
        Ok(value) => value,
        Err(_) => panic!("valid descriptor was rejected"),
    };
    assert_eq!(spec.id, "dev-_01");
    assert!(spec.enabled);
    assert_eq!(
        spec.tags,
        vec![
            "alpha".to_string(),
            "beta-2".to_string(),
            "alpha".to_string(),
        ]
    );
    assert_eq!(input, before);
}

#[test]
fn parses_off_and_an_empty_tag_field() {
    let spec = match parse_device_spec("x, off,   ") {
        Ok(value) => value,
        Err(_) => panic!("valid descriptor was rejected"),
    };
    assert_eq!(spec.id, "x");
    assert!(!spec.enabled);
    assert!(spec.tags.is_empty());
}

#[test]
fn distinguishes_empty_input_from_bad_identifier() {
    assert!(matches!(
        parse_device_spec(" \t\n "),
        Err(ParseDeviceError::EmptyInput)
    ));
    assert!(matches!(
        parse_device_spec(" ,on,"),
        Err(ParseDeviceError::InvalidId)
    ));
    assert!(matches!(
        parse_device_spec("bad id,on,"),
        Err(ParseDeviceError::InvalidId)
    ));
    assert!(matches!(
        parse_device_spec("é,on,"),
        Err(ParseDeviceError::InvalidId)
    ));
}

#[test]
fn field_count_is_determined_only_by_commas() {
    for input in ["a,on", "a,on::", "a,on,,", "a,on,x,y"] {
        assert!(matches!(
            parse_device_spec(input),
            Err(ParseDeviceError::WrongFieldCount)
        ));
    }
}

#[test]
fn enabled_flag_is_exact_after_trimming() {
    for input in ["a,ON,", "a,on:off,", "a,on::,", "a,true,"] {
        assert!(matches!(
            parse_device_spec(input),
            Err(ParseDeviceError::InvalidEnabled)
        ));
    }
}

#[test]
fn rejects_empty_or_invalid_tags_in_nonempty_lists() {
    for input in [
        "a,on,::",
        "a,on,x:",
        "a,on,:x",
        "a,on,x::y",
        "a,on,x:   :y",
        "a,on,x y",
        "a,on,é",
    ] {
        assert!(matches!(
            parse_device_spec(input),
            Err(ParseDeviceError::InvalidTag)
        ));
    }
}

