package solution

import (
	"encoding/json"
	"errors"
	"sort"
	"strconv"
	"strings"
)

type OutputFormat int

const (
	FormatLines OutputFormat = iota
	FormatJSON
)

func validIdentifier(key string) bool {
	if key == "" {
		return false
	}
	for i := 0; i < len(key); i++ {
		ch := key[i]
		letter := ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z'
		if i == 0 {
			if !letter && ch != '_' {
				return false
			}
		} else if !letter && !(ch >= '0' && ch <= '9') && ch != '_' {
			return false
		}
	}
	return true
}

func RenderBindings(values map[string]string, format OutputFormat) (string, error) {
	if format != FormatLines && format != FormatJSON {
		return "", errors.New("unsupported format")
	}
	keys := make([]string, 0, len(values))
	for key := range values {
		if !validIdentifier(key) {
			return "", errors.New("invalid key")
		}
		keys = append(keys, key)
	}
	sort.Strings(keys)

	var b strings.Builder
	if format == FormatLines {
		for _, key := range keys {
			b.WriteString(key)
			b.WriteString(" = ")
			b.WriteString(strconv.Quote(values[key]))
			b.WriteByte('\n')
		}
		return b.String(), nil
	}

	b.WriteByte('{')
	for index, key := range keys {
		if index > 0 {
			b.WriteByte(',')
		}
		encodedKey, _ := json.Marshal(key)
		encodedValue, _ := json.Marshal(values[key])
		b.Write(encodedKey)
		b.WriteByte(':')
		b.Write(encodedValue)
	}
	b.WriteString("}\n")
	return b.String(), nil
}

