package solution

import (
	"bytes"
	"encoding/json"
	"reflect"
	"sort"
	"strings"
	"testing"
)

func TestRenderBindingsLinesSortedQuotedAndStable(t *testing.T) {
	values := map[string]string{
		"z9": "line\nquote\"",
		"_a": "雪",
		"A":  "tab\t",
	}
	before := map[string]string{"z9": "line\nquote\"", "_a": "雪", "A": "tab\t"}

	got, err := RenderBindings(values, FormatLines)
	if err != nil {
		t.Fatalf("RenderBindings returned error: %v", err)
	}
	want := "A = \"tab\\t\"\n_a = \"雪\"\nz9 = \"line\\nquote\\\"\"\n"
	if got != want {
		t.Fatalf("unexpected output:\n got %q\nwant %q", got, want)
	}
	if !reflect.DeepEqual(values, before) {
		t.Fatalf("input map mutated: got %#v", values)
	}

	again, err := RenderBindings(values, FormatLines)
	if err != nil || again != got {
		t.Fatalf("output is not deterministic: %q, %v", again, err)
	}
}

func TestRenderBindingsJSONSortedValidCompactAndQuoted(t *testing.T) {
	values := map[string]string{
		"b": "snow 雪 and spaces",
		"A": "quoted\"",
		"a": "\\",
		"ctl": "\a\v\x00",
	}
	before := map[string]string{
		"b": "snow 雪 and spaces",
		"A": "quoted\"",
		"a": "\\",
		"ctl": "\a\v\x00",
	}

	got, err := RenderBindings(values, FormatJSON)
	if err != nil {
		t.Fatalf("RenderBindings returned error: %v", err)
	}
	if !strings.HasSuffix(got, "\n") || strings.Count(got, "\n") != 1 {
		t.Fatalf("JSON output must have exactly one final newline: %q", got)
	}
	object := []byte(strings.TrimSuffix(got, "\n"))
	var compact bytes.Buffer
	if err := json.Compact(&compact, object); err != nil {
		t.Fatalf("output is invalid JSON: %v", err)
	}
	if !bytes.Equal(compact.Bytes(), object) {
		t.Fatalf("JSON object is not compact: %q", object)
	}

	var decoded map[string]string
	if err := json.Unmarshal([]byte(got), &decoded); err != nil {
		t.Fatalf("output is invalid JSON: %v", err)
	}
	if !reflect.DeepEqual(decoded, values) {
		t.Fatalf("decoded output differs: %#v", decoded)
	}

	dec := json.NewDecoder(bytes.NewReader(object))
	if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
		t.Fatalf("missing object start: %v, %v", tok, err)
	}
	var emitted []string
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			t.Fatal(err)
		}
		key, ok := tok.(string)
		if !ok {
			t.Fatalf("object key token has type %T", tok)
		}
		emitted = append(emitted, key)
		var value string
		if err := dec.Decode(&value); err != nil {
			t.Fatal(err)
		}
	}
	if tok, err := dec.Token(); err != nil || tok != json.Delim('}') {
		t.Fatalf("missing object end: %v, %v", tok, err)
	}
	wantKeys := make([]string, 0, len(values))
	for key := range values {
		wantKeys = append(wantKeys, key)
	}
	sort.Strings(wantKeys)
	if !reflect.DeepEqual(emitted, wantKeys) {
		t.Fatalf("key order = %#v, want %#v", emitted, wantKeys)
	}
	if !reflect.DeepEqual(values, before) {
		t.Fatal("input map was mutated")
	}

	again, err := RenderBindings(values, FormatJSON)
	if err != nil || again != got {
		t.Fatalf("JSON output is not deterministic: %q, %v", again, err)
	}
}

func TestRenderBindingsEmptyAndNil(t *testing.T) {
	for _, values := range []map[string]string{nil, {}} {
		lines, err := RenderBindings(values, FormatLines)
		if err != nil || lines != "" {
			t.Fatalf("empty lines: got %q, %v", lines, err)
		}
		js, err := RenderBindings(values, FormatJSON)
		if err != nil || js != "{}\n" {
			t.Fatalf("empty JSON: got %q, %v", js, err)
		}
	}
}

func TestRenderBindingsRejectsInvalidKeysAndFormats(t *testing.T) {
	invalid := []string{"", "9abc", "a-b", "a b", "é", "aé", "a.b"}
	for _, key := range invalid {
		for _, format := range []OutputFormat{FormatLines, FormatJSON} {
			got, err := RenderBindings(map[string]string{key: "value"}, format)
			if err == nil || got != "" {
				t.Errorf("key %q, format %d: got %q, %v; want empty result and error", key, format, got, err)
			}
		}
	}
	for _, format := range []OutputFormat{-1, 2, 99} {
		got, err := RenderBindings(map[string]string{}, format)
		if err == nil || got != "" {
			t.Errorf("format %d: got %q, %v; want empty result and error", format, got, err)
		}
	}
}

