package solution

import (
	"errors"
	"sort"
)

type Component struct {
	Name    string
	Scope   string
	Release string
	Quota   int
}

type componentKey struct {
	scope string
	name  string
}

type Registry struct {
	items map[componentKey]Component
}

func NewRegistry() *Registry {
	return &Registry{items: make(map[componentKey]Component)}
}

func (r *Registry) Create(name, scope, release string) (Component, error) {
	if name == "" || scope == "" || release == "" {
		return Component{}, errors.New("all fields are required")
	}
	key := componentKey{scope: scope, name: name}
	if _, exists := r.items[key]; exists {
		return Component{}, errors.New("component already exists")
	}
	component := Component{Name: name, Scope: scope, Release: release, Quota: 64}
	r.items[key] = component
	return component, nil
}

func (r *Registry) List(scope string) []Component {
	components := make([]Component, 0)
	if scope == "" {
		return components
	}
	for _, component := range r.items {
		if component.Scope == scope {
			components = append(components, component)
		}
	}
	sort.Slice(components, func(i, j int) bool {
		return components[i].Name < components[j].Name
	})
	return components
}

func (r *Registry) Get(name, scope string) (Component, error) {
	if name == "" || scope == "" {
		return Component{}, errors.New("name and scope are required")
	}
	component, exists := r.items[componentKey{scope: scope, name: name}]
	if !exists {
		return Component{}, errors.New("component not found")
	}
	return component, nil
}

func (r *Registry) Delete(name, scope string) error {
	if name == "" || scope == "" {
		return errors.New("name and scope are required")
	}
	key := componentKey{scope: scope, name: name}
	if _, exists := r.items[key]; !exists {
		return errors.New("component not found")
	}
	delete(r.items, key)
	return nil
}

