package solution

import (
	"reflect"
	"testing"
)

func TestRegistryLifecycleAndScopeIdentity(t *testing.T) {
	r := NewRegistry()
	if r == nil {
		t.Fatal("NewRegistry returned nil")
	}

	created, err := r.Create("worker", "prod", "v1")
	if err != nil {
		t.Fatal(err)
	}
	want := Component{Name: "worker", Scope: "prod", Release: "v1", Quota: 64}
	if created != want {
		t.Fatalf("created %#v, want %#v", created, want)
	}
	if _, err := r.Create("worker", "staging", "v2"); err != nil {
		t.Fatalf("same name in another scope must be allowed: %v", err)
	}
	if _, err := r.Create("worker", "prod", "v3"); err == nil {
		t.Fatal("duplicate scope/name was accepted")
	}

	got, err := r.Get("worker", "prod")
	if err != nil || got != want {
		t.Fatalf("Get returned %#v, %v", got, err)
	}
	if err := r.Delete("worker", "prod"); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Get("worker", "prod"); err == nil {
		t.Fatal("deleted component still found")
	}
	if _, err := r.Get("worker", "staging"); err != nil {
		t.Fatalf("delete affected another scope: %v", err)
	}
	if err := r.Delete("worker", "prod"); err == nil {
		t.Fatal("deleting a missing component must fail")
	}
}

func TestRegistryTreatsScopeAndNameAsExactPair(t *testing.T) {
	r := NewRegistry()
	first := Component{Name: "c", Scope: "a\x00b", Release: "first", Quota: 64}
	second := Component{Name: "b\x00c", Scope: "a", Release: "second", Quota: 64}
	for _, c := range []Component{first, second} {
		got, err := r.Create(c.Name, c.Scope, c.Release)
		if err != nil || got != c {
			t.Fatalf("Create(%#v) = %#v, %v", c, got, err)
		}
	}
	for _, c := range []Component{first, second} {
		got, err := r.Get(c.Name, c.Scope)
		if err != nil || got != c {
			t.Fatalf("Get(%q, %q) = %#v, %v", c.Name, c.Scope, got, err)
		}
		listed := r.List(c.Scope)
		if !reflect.DeepEqual(listed, []Component{c}) {
			t.Fatalf("List(%q) = %#v, want %#v", c.Scope, listed, []Component{c})
		}
	}
	if err := r.Delete(first.Name, first.Scope); err != nil {
		t.Fatal(err)
	}
	if got, err := r.Get(second.Name, second.Scope); err != nil || got != second {
		t.Fatalf("deleting first affected second: %#v, %v", got, err)
	}
	if err := r.Delete(second.Name, second.Scope); err != nil {
		t.Fatal(err)
	}
}

func TestRegistryListOrderingFilteringAndIsolation(t *testing.T) {
	r := NewRegistry()
	for _, c := range []Component{
		{Name: "z", Scope: "one", Release: "1"},
		{Name: "a", Scope: "one", Release: "2"},
		{Name: "m", Scope: "two", Release: "3"},
	} {
		if _, err := r.Create(c.Name, c.Scope, c.Release); err != nil {
			t.Fatal(err)
		}
	}
	got := r.List("one")
	want := []Component{
		{Name: "a", Scope: "one", Release: "2", Quota: 64},
		{Name: "z", Scope: "one", Release: "1", Quota: 64},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("List got %#v, want %#v", got, want)
	}
	got[0].Release = "changed"
	got[1] = Component{}
	if again := r.List("one"); !reflect.DeepEqual(again, want) {
		t.Fatalf("mutating returned slice affected registry: %#v", again)
	}
	if got := r.List("missing"); len(got) != 0 {
		t.Fatalf("missing scope returned %#v", got)
	}
}

func TestRegistryEmptyInputsAndEmptyScopeList(t *testing.T) {
	r := NewRegistry()
	for _, args := range [][3]string{{"", "s", "r"}, {"n", "", "r"}, {"n", "s", ""}} {
		if _, err := r.Create(args[0], args[1], args[2]); err == nil {
			t.Errorf("Create%q accepted an empty field", args)
		}
	}
	for _, pair := range [][2]string{{"", "s"}, {"n", ""}, {"", ""}} {
		if _, err := r.Get(pair[0], pair[1]); err == nil {
			t.Errorf("Get%q accepted empty identifier", pair)
		}
		if err := r.Delete(pair[0], pair[1]); err == nil {
			t.Errorf("Delete%q accepted empty identifier", pair)
		}
	}
	if got := r.List(""); got == nil || len(got) != 0 {
		t.Fatalf("List(empty) = %#v, want non-nil empty", got)
	}
}

