package solution

import (
	"reflect"
	"testing"
)

func TestRouterResolveOrderParametersAndFreshMaps(t *testing.T) {
	routes := []Route{
		{Method: "GET", Pattern: "/users/{id}", Name: "by-id"},
		{Method: "GET", Pattern: "/users/me", Name: "me"},
		{Method: "POST", Pattern: "/users/{id}/items/{item}", Name: "item"},
		{Method: "GET", Pattern: "/", Name: "root"},
	}
	r, err := NewRouter(routes)
	if err != nil {
		t.Fatal(err)
	}

	name, params, ok := r.Resolve("GET", "/users/me")
	if !ok || name != "by-id" || !reflect.DeepEqual(params, map[string]string{"id": "me"}) {
		t.Fatalf("first matching route did not win: %q %#v %v", name, params, ok)
	}
	params["id"] = "changed"
	_, again, ok := r.Resolve("GET", "/users/me")
	if !ok || again["id"] != "me" {
		t.Fatalf("parameter map was not fresh: %#v", again)
	}

	name, params, ok = r.Resolve("POST", "/users/u1/items/i2")
	if !ok || name != "item" || !reflect.DeepEqual(params, map[string]string{"id": "u1", "item": "i2"}) {
		t.Fatalf("unexpected multi-parameter result: %q %#v %v", name, params, ok)
	}

	name, params, ok = r.Resolve("GET", "/")
	if !ok || name != "root" || params == nil || len(params) != 0 {
		t.Fatalf("literal route must return fresh empty map: %q %#v %v", name, params, ok)
	}
}

func TestRouterUsesExactMethodPatternPairIdentity(t *testing.T) {
	r, err := NewRouter([]Route{
		{Method: "GET\x00/x", Pattern: "/y", Name: "method-nul"},
		{Method: "GET", Pattern: "/x\x00/y", Name: "path-nul"},
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		method, path, want string
	}{
		{"GET\x00/x", "/y", "method-nul"},
		{"GET", "/x\x00/y", "path-nul"},
	} {
		name, params, ok := r.Resolve(tc.method, tc.path)
		if !ok || name != tc.want || params == nil || len(params) != 0 {
			t.Fatalf("Resolve(%q, %q) = %q, %#v, %v", tc.method, tc.path, name, params, ok)
		}
		params["changed"] = "yes"
		_, again, ok := r.Resolve(tc.method, tc.path)
		if !ok || len(again) != 0 {
			t.Fatalf("successful parameter maps are not fresh: %#v", again)
		}
	}
}

func TestRouterCopiesConstructionInput(t *testing.T) {
	routes := []Route{{Method: "GET", Pattern: "/old", Name: "old"}}
	r, err := NewRouter(routes)
	if err != nil {
		t.Fatal(err)
	}
	routes[0] = Route{Method: "POST", Pattern: "/new", Name: "new"}
	if name, _, ok := r.Resolve("GET", "/old"); !ok || name != "old" {
		t.Fatalf("router retained caller's route slice: %q %v", name, ok)
	}
	if _, _, ok := r.Resolve("POST", "/new"); ok {
		t.Fatal("mutation of source route slice changed router")
	}
}

func TestRouterRejectsInvalidRoutes(t *testing.T) {
	invalid := [][]Route{
		{{Method: "", Pattern: "/x", Name: "n"}},
		{{Method: "GET", Pattern: "/x", Name: ""}},
		{{Method: "GET", Pattern: "x", Name: "n"}},
		{{Method: "GET", Pattern: "/x/", Name: "n"}},
		{{Method: "GET", Pattern: "//x", Name: "n"}},
		{{Method: "GET", Pattern: "/{}", Name: "n"}},
		{{Method: "GET", Pattern: "/{x}/{x}", Name: "n"}},
		{{Method: "GET", Pattern: "/{x}suffix", Name: "n"}},
		{{Method: "GET", Pattern: "/x", Name: "one"}, {Method: "GET", Pattern: "/x", Name: "two"}},
	}
	for i, routes := range invalid {
		if _, err := NewRouter(routes); err == nil {
			t.Errorf("case %d: expected error", i)
		}
	}
}

func TestRouterFailuresHaveExactFailureTuple(t *testing.T) {
	r, err := NewRouter([]Route{{Method: "GET", Pattern: "/a/{x}", Name: "n"}})
	if err != nil {
		t.Fatal(err)
	}
	cases := [][2]string{
		{"get", "/a/b"},
		{"GET", "/a"},
		{"GET", "/a/b/c"},
		{"GET", "/a/"},
		{"GET", "/a//b"},
		{"GET", "a/b"},
		{"GET", "/a/{x}"},
	}
	for _, tc := range cases {
		name, params, ok := r.Resolve(tc[0], tc[1])
		if name != "" || params != nil || ok {
			t.Errorf("Resolve%q = %q, %#v, %v; want failure tuple", tc, name, params, ok)
		}
	}
}

func TestNewRouterAllowsEmptyRoutes(t *testing.T) {
	r, err := NewRouter(nil)
	if err != nil || r == nil {
		t.Fatalf("NewRouter(nil) = %#v, %v", r, err)
	}
	if name, params, ok := r.Resolve("GET", "/"); name != "" || params != nil || ok {
		t.Fatalf("empty router resolved a path: %q %#v %v", name, params, ok)
	}
}

