package solution

import (
	"math"
	"reflect"
	"testing"
)

func TestPowersOfThreeGeneratorSequenceExhaustionAndNoOverflow(t *testing.T) {
	gen := NewPowersOfThree()
	want := uint64(1)
	count := 0
	for {
		got, ok := gen()
		if !ok {
			if got != 0 {
				t.Fatalf("exhausted generator returned %d, false", got)
			}
			break
		}
		if got != want {
			t.Fatalf("value %d: got %d, want %d", count, got, want)
		}
		count++
		if want <= math.MaxUint64/3 {
			want *= 3
		}
	}
	if count != 41 {
		t.Fatalf("returned %d powers, want 41", count)
	}
	for i := 0; i < 3; i++ {
		if got, ok := gen(); got != 0 || ok {
			t.Fatalf("post-exhaustion call %d returned %d, %v", i, got, ok)
		}
	}
}

func TestNewPowersOfThreeHasIndependentState(t *testing.T) {
	a := NewPowersOfThree()
	b := NewPowersOfThree()
	if got, ok := a(); got != 1 || !ok {
		t.Fatalf("a first = %d, %v", got, ok)
	}
	if got, ok := a(); got != 3 || !ok {
		t.Fatalf("a second = %d, %v", got, ok)
	}
	if got, ok := b(); got != 1 || !ok {
		t.Fatalf("b first = %d, %v; generators share state", got, ok)
	}
}

func TestPowersOfThreeBoundsAndSliceIsolation(t *testing.T) {
	for _, n := range []int{-10, -1, 0} {
		got := PowersOfThree(n)
		if got == nil || len(got) != 0 {
			t.Errorf("PowersOfThree(%d) = %#v, want non-nil empty", n, got)
		}
	}
	want := []uint64{1, 3, 9, 27, 81}
	got := PowersOfThree(5)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
	got[0] = 999
	if again := PowersOfThree(5); !reflect.DeepEqual(again, want) {
		t.Fatalf("returned slices share state: %#v", again)
	}

	all := PowersOfThree(1000)
	if len(all) != 41 || all[0] != 1 || all[len(all)-1] != 12157665459056928801 {
		t.Fatalf("all powers = %#v", all)
	}
	for i := 1; i < len(all); i++ {
		if all[i-1] > math.MaxUint64/3 || all[i] != all[i-1]*3 {
			t.Fatalf("invalid recurrence at %d: %d then %d", i, all[i-1], all[i])
		}
	}
}

func TestPowersOfThreeNativeMaxIntRequestStaysFinite(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	got := PowersOfThree(maxInt)
	if len(got) != 41 || got[0] != 1 || got[len(got)-1] != 12157665459056928801 {
		t.Fatalf("PowersOfThree(MaxInt) returned %#v", got)
	}
}

