package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestInventoryLifecycleAndSentinelErrors(t *testing.T) {
	inv := NewInventory()
	if inv == nil {
		t.Fatal("NewInventory returned nil")
	}
	a := Asset{ID: "10", Name: "router", Zone: "west", Tags: []string{"edge", "blue"}}
	if err := inv.Add(a); err != nil {
		t.Fatal(err)
	}
	if err := inv.Add(a); !errors.Is(err, ErrAssetExists) {
		t.Fatalf("duplicate error = %v, want ErrAssetExists", err)
	}
	got, err := inv.Get("10")
	if err != nil || !reflect.DeepEqual(got, a) {
		t.Fatalf("Get = %#v, %v", got, err)
	}

	replacement := Asset{ID: "10", Name: "switch", Zone: "east", Tags: []string{"green"}}
	if err := inv.Update(replacement); err != nil {
		t.Fatal(err)
	}
	got, _ = inv.Get("10")
	if !reflect.DeepEqual(got, replacement) {
		t.Fatalf("Update stored %#v, want %#v", got, replacement)
	}
	if err := inv.Delete("10"); err != nil {
		t.Fatal(err)
	}
	if _, err := inv.Get("10"); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("Get missing error = %v", err)
	}
	if err := inv.Delete("10"); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("Delete missing error = %v", err)
	}
	if err := inv.Update(replacement); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("Update missing error = %v", err)
	}
}

func TestInventoryAcceptsArbitrarilyLargeCanonicalDecimalID(t *testing.T) {
	inv := NewInventory()
	id := "18446744073709551616"
	a := Asset{ID: id, Name: "large", Zone: "z", Tags: []string{"original"}}
	if err := inv.Add(a); err != nil {
		t.Fatalf("Add rejected canonical decimal ID: %v", err)
	}
	got, err := inv.Get(id)
	if err != nil || !reflect.DeepEqual(got, a) {
		t.Fatalf("Get = %#v, %v; want %#v", got, err, a)
	}
	replacement := Asset{ID: id, Name: "updated", Zone: "new", Tags: []string{"stored"}}
	if err := inv.Update(replacement); err != nil {
		t.Fatal(err)
	}
	replacement.Tags[0] = "mutated"
	got, err = inv.Get(id)
	if err != nil || got.ID != id || !reflect.DeepEqual(got.Tags, []string{"stored"}) {
		t.Fatalf("Update did not preserve ID or copy tags: %#v, %v", got, err)
	}
	if err := inv.Delete(id); err != nil {
		t.Fatal(err)
	}
	if _, err := inv.Get(id); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("large ID remained after Delete: %v", err)
	}
}

func TestInventoryValidationAndAtomicUpdate(t *testing.T) {
	inv := NewInventory()
	invalid := []Asset{
		{ID: "", Name: "n", Zone: "z"},
		{ID: "0", Name: "n", Zone: "z"},
		{ID: "00", Name: "n", Zone: "z"},
		{ID: "01", Name: "n", Zone: "z"},
		{ID: "+1", Name: "n", Zone: "z"},
		{ID: "-1", Name: "n", Zone: "z"},
		{ID: "1 ", Name: "n", Zone: "z"},
		{ID: "1a", Name: "n", Zone: "z"},
		{ID: "１２", Name: "n", Zone: "z"},
		{ID: "1", Name: "", Zone: "z"},
		{ID: "1", Name: "n", Zone: ""},
		{ID: "1", Name: "n", Zone: "z", Tags: []string{"ok", ""}},
	}
	for i, a := range invalid {
		if err := inv.Add(a); !errors.Is(err, ErrInvalidAsset) {
			t.Errorf("invalid case %d returned %v", i, err)
		}
	}
	if err := inv.Add(Asset{ID: "1", Name: "original", Zone: "z", Tags: []string{"a"}}); err != nil {
		t.Fatal(err)
	}
	if err := inv.Update(Asset{ID: "1", Name: "", Zone: "new"}); !errors.Is(err, ErrInvalidAsset) {
		t.Fatalf("invalid update error = %v", err)
	}
	got, _ := inv.Get("1")
	if got.Name != "original" || got.Zone != "z" || !reflect.DeepEqual(got.Tags, []string{"a"}) {
		t.Fatalf("invalid update changed stored asset: %#v", got)
	}
}

func TestInventoryCopiesTagsAtEveryBoundary(t *testing.T) {
	inv := NewInventory()
	input := Asset{ID: "2", Name: "n", Zone: "z", Tags: []string{"one", "two"}}
	if err := inv.Add(input); err != nil {
		t.Fatal(err)
	}
	input.Tags[0] = "argument-mutated"
	got, _ := inv.Get("2")
	if got.Tags[0] != "one" {
		t.Fatalf("Add retained tag slice: %#v", got.Tags)
	}
	got.Tags[0] = "get-mutated"
	again, _ := inv.Get("2")
	if again.Tags[0] != "one" {
		t.Fatalf("Get exposed tag slice: %#v", again.Tags)
	}
	snapshot := inv.Snapshot()
	s := snapshot["2"]
	s.Tags[0] = "snapshot-mutated"
	snapshot["2"] = Asset{}
	again, _ = inv.Get("2")
	if again.Tags[0] != "one" || again.Name != "n" {
		t.Fatalf("Snapshot exposed storage: %#v", again)
	}
}

func TestInventoryIDsSnapshotAndClear(t *testing.T) {
	inv := NewInventory()
	if ids := inv.IDs(); ids == nil || len(ids) != 0 {
		t.Fatalf("empty IDs = %#v", ids)
	}
	if snap := inv.Snapshot(); snap == nil || len(snap) != 0 {
		t.Fatalf("empty Snapshot = %#v", snap)
	}
	for _, id := range []string{"2", "10", "1"} {
		if err := inv.Add(Asset{ID: id, Name: id, Zone: "z"}); err != nil {
			t.Fatal(err)
		}
	}
	if got, want := inv.IDs(), []string{"1", "10", "2"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("IDs = %#v, want %#v", got, want)
	}
	ids := inv.IDs()
	ids[0] = "changed"
	if inv.IDs()[0] != "1" {
		t.Fatal("IDs returned aliased storage")
	}
	inv.Clear()
	if ids := inv.IDs(); ids == nil || len(ids) != 0 {
		t.Fatalf("after Clear IDs = %#v", ids)
	}
	if _, err := inv.Get("1"); !errors.Is(err, ErrAssetNotFound) {
		t.Fatalf("Clear did not remove assets: %v", err)
	}
}

