package solution

import (
	"reflect"
	"strconv"
	"testing"
	"time"
)

func assetRecordsFixture() []AssetRecord {
	return []AssetRecord{
		{ID: "c", Owner: "alice", Labels: []string{"red", "x"}, Created: "2024-01-03T00:00:00Z", Modified: "2024-01-04T01:02:03+02:00", Attributes: map[string][]string{"k": {"c1", "c2"}}},
		{ID: "a", Owner: "alice", Labels: []string{"blue", "red"}, Created: "2024-01-01T00:00:00Z", Modified: "2024-01-02T00:00:00Z"},
		{ID: "b", Owner: "bob", Labels: []string{"red"}, Created: "2024-01-02T00:00:00Z", Modified: "2024-01-02T00:00:00Z"},
	}
}

func TestListAssetsFiltersSortsAndPaginates(t *testing.T) {
	records := assetRecordsFixture()
	query := AssetQuery{Owner: "alice", Label: "red", CreatedOnOrAfter: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC), PageSize: 1}
	rows, cursor, err := ListAssets(records, query)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 1 || rows[0].ID != "a" || cursor != "1" {
		t.Fatalf("first page = %#v, cursor %q", rows, cursor)
	}
	if !rows[0].Created.Equal(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)) {
		t.Fatalf("wrong parsed creation time: %v", rows[0].Created)
	}

	query.Cursor = cursor
	rows, cursor, err = ListAssets(records, query)
	if err != nil {
		t.Fatal(err)
	}
	if len(rows) != 1 || rows[0].ID != "c" || cursor != "" {
		t.Fatalf("second page = %#v, cursor %q", rows, cursor)
	}
	wantModified, _ := time.Parse(time.RFC3339, records[0].Modified)
	if !rows[0].Modified.Equal(wantModified) {
		t.Fatalf("wrong parsed modified time: %v", rows[0].Modified)
	}
}

func TestListAssetsInclusiveDateAndExactFilters(t *testing.T) {
	records := assetRecordsFixture()
	cutoff, _ := time.Parse(time.RFC3339, "2024-01-02T00:00:00Z")
	rows, cursor, err := ListAssets(records, AssetQuery{Label: "red", CreatedOnOrAfter: cutoff, PageSize: 10})
	if err != nil || cursor != "" || len(rows) != 2 {
		t.Fatalf("ListAssets = %#v, %q, %v", rows, cursor, err)
	}
	if got, want := []string{rows[0].ID, rows[1].ID}, []string{"b", "c"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("inclusive filter IDs = %#v, want %#v", got, want)
	}
	rows, _, err = ListAssets(records, AssetQuery{Owner: "Alice", PageSize: 10})
	if err != nil || len(rows) != 0 {
		t.Fatalf("owner matching was not exact: %#v, %v", rows, err)
	}
	rows, _, err = ListAssets(records, AssetQuery{Label: "RED", PageSize: 10})
	if err != nil || len(rows) != 0 {
		t.Fatalf("label matching was not exact: %#v, %v", rows, err)
	}
}

func TestListAssetsValidatesAllRecordTimestampsBeforeFiltering(t *testing.T) {
	cases := [][]AssetRecord{
		{{ID: "ok", Owner: "wanted", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}, {ID: "bad", Owner: "excluded", Created: "not-a-time", Modified: "2024-01-01T00:00:00Z"}},
		{{ID: "bad", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "bad"}},
	}
	for i, records := range cases {
		rows, cursor, err := ListAssets(records, AssetQuery{Owner: "wanted", PageSize: 10})
		if err == nil || rows != nil || cursor != "" {
			t.Errorf("case %d = %#v, %q, %v; want nil, empty, error", i, rows, cursor, err)
		}
	}
}

func TestListAssetsRejectsInvalidIDsAcrossAllRecords(t *testing.T) {
	cases := [][]AssetRecord{
		{{ID: "dup", Owner: "wanted", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}, {ID: "dup", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}},
		{{ID: "", Owner: "excluded", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}},
	}
	for i, records := range cases {
		if _, _, err := ListAssets(records, AssetQuery{Owner: "wanted", PageSize: 10}); err == nil {
			t.Errorf("case %d: expected error", i)
		}
	}
}

func TestListAssetsCursorValidationAndBoundaries(t *testing.T) {
	records := assetRecordsFixture()
	invalid := []string{"+1", "-1", " 1", "1 ", "01", "00", "1.0", "18446744073709551616"}
	for _, cursor := range invalid {
		if _, _, err := ListAssets(records, AssetQuery{PageSize: 1, Cursor: cursor}); err == nil {
			t.Errorf("cursor %q was accepted", cursor)
		}
	}
	tooLarge := strconv.Itoa(len(records) + 1)
	if _, _, err := ListAssets(records, AssetQuery{PageSize: 1, Cursor: tooLarge}); err == nil {
		t.Fatalf("offset beyond match count was accepted")
	}
	rows, next, err := ListAssets(records, AssetQuery{PageSize: 2, Cursor: "0"})
	if err != nil || len(rows) != 2 || rows[0].ID != "a" || next != "2" {
		t.Fatalf("canonical zero cursor failed: %#v, %q, %v", rows, next, err)
	}
	rows, next, err = ListAssets(records, AssetQuery{PageSize: 2, Cursor: strconv.Itoa(len(records))})
	if err != nil || len(rows) != 0 || next != "" {
		t.Fatalf("terminal offset failed: %#v, %q, %v", rows, next, err)
	}
}

func TestListAssetsNativeMaxPageSizeWithCursor(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	one := []AssetRecord{{ID: "a", Created: "2024-01-01T00:00:00Z", Modified: "2024-01-01T00:00:00Z"}}
	rows, next, err := ListAssets(one, AssetQuery{PageSize: maxInt, Cursor: "1"})
	if err != nil || len(rows) != 0 || next != "" {
		t.Fatalf("one-record terminal page = %#v, %q, %v", rows, next, err)
	}
	two := append(one, AssetRecord{ID: "b", Created: "2024-01-02T00:00:00Z", Modified: "2024-01-02T00:00:00Z"})
	rows, next, err = ListAssets(two, AssetQuery{PageSize: maxInt, Cursor: "1"})
	if err != nil || len(rows) != 1 || rows[0].ID != "b" || next != "" {
		t.Fatalf("two-record page = %#v, %q, %v", rows, next, err)
	}
}

func TestListAssetsRejectsNonPositivePageSize(t *testing.T) {
	for _, size := range []int{-1, 0} {
		if _, _, err := ListAssets(nil, AssetQuery{PageSize: size}); err == nil {
			t.Errorf("PageSize %d was accepted", size)
		}
	}
}

func TestListAssetsDeepCopiesAndDoesNotMutateInput(t *testing.T) {
	records := assetRecordsFixture()
	before := assetRecordsFixture()
	rows, _, err := ListAssets(records, AssetQuery{PageSize: 10})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(records, before) {
		t.Fatal("input records mutated during call")
	}
	var c *AssetRow
	for i := range rows {
		if rows[i].ID == "c" {
			c = &rows[i]
		}
	}
	if c == nil {
		t.Fatal("missing row c")
	}
	c.Labels[0] = "changed"
	c.Attributes["k"][0] = "changed"
	c.Attributes["new"] = []string{"x"}
	if !reflect.DeepEqual(records, before) {
		t.Fatal("returned row aliases input records")
	}
	again, _, err := ListAssets(records, AssetQuery{PageSize: 10})
	if err != nil {
		t.Fatal(err)
	}
	for _, row := range again {
		if row.ID == "c" && (row.Labels[0] != "red" || row.Attributes["k"][0] != "c1") {
			t.Fatalf("later result shares mutable storage: %#v", row)
		}
	}
}

func TestListAssetsEmptyInput(t *testing.T) {
	rows, cursor, err := ListAssets(nil, AssetQuery{PageSize: 1})
	if err != nil || len(rows) != 0 || cursor != "" {
		t.Fatalf("empty input = %#v, %q, %v", rows, cursor, err)
	}
}

