package solution

import (
	"errors"
	"fmt"
	"strings"
)

type Segment struct {
	Code string
	Span int
}

type Layout struct {
	Material      string
	Capacity, Gap int
	Segments      []Segment
	Marks         []int
}

func EncodeLayout(layout Layout) (string, error) {
	if layout.Material == "" || layout.Capacity < 0 || layout.Gap < 0 {
		return "", errors.New("invalid layout")
	}

	used := 0
	for index, segment := range layout.Segments {
		if segment.Code == "" || segment.Span <= 0 {
			return "", errors.New("invalid segment")
		}
		if index > 0 {
			if layout.Gap > layout.Capacity-used {
				return "", errors.New("layout exceeds capacity")
			}
			used += layout.Gap
		}
		if segment.Span > layout.Capacity-used {
			return "", errors.New("layout exceeds capacity")
		}
		used += segment.Span
	}

	for _, mark := range layout.Marks {
		if mark < 0 || mark > layout.Capacity {
			return "", errors.New("invalid mark")
		}
	}

	var builder strings.Builder
	fmt.Fprintf(&builder, "LAYOUT/1\n[base]\nmaterial=%s\ncapacity=%d\n[segments]\n", layout.Material, layout.Capacity)
	for _, segment := range layout.Segments {
		fmt.Fprintf(&builder, "%s:%d\n", segment.Code, segment.Span)
	}
	builder.WriteString("[marks]\n")
	for _, mark := range layout.Marks {
		fmt.Fprintf(&builder, "%d\n", mark)
	}
	fmt.Fprintf(&builder, "[totals]\nused=%d\nremaining=%d\n", used, layout.Capacity-used)
	return builder.String(), nil
}

