package solution

import (
	"strconv"
	"testing"
)

func TestEncodeLayoutExactFormatOrderAndTotals(t *testing.T) {
	layout := Layout{
		Material: "steel",
		Capacity: 20,
		Gap:      2,
		Segments: []Segment{{Code: "B", Span: 3}, {Code: "A", Span: 4}},
		Marks:    []int{20, 0, 7},
	}
	got, err := EncodeLayout(layout)
	if err != nil {
		t.Fatal(err)
	}
	want := "LAYOUT/1\n[base]\nmaterial=steel\ncapacity=20\n[segments]\nB:3\nA:4\n[marks]\n20\n0\n7\n[totals]\nused=9\nremaining=11\n"
	if got != want {
		t.Fatalf("output differs:\n got %q\nwant %q", got, want)
	}
	if layout.Segments[0] != (Segment{Code: "B", Span: 3}) || layout.Marks[0] != 20 {
		t.Fatal("input slices were mutated")
	}
}

func TestEncodeLayoutEmptySectionsAndGapOnlyBetweenSegments(t *testing.T) {
	got, err := EncodeLayout(Layout{Material: "wood", Capacity: 5, Gap: 99})
	if err != nil {
		t.Fatal(err)
	}
	want := "LAYOUT/1\n[base]\nmaterial=wood\ncapacity=5\n[segments]\n[marks]\n[totals]\nused=0\nremaining=5\n"
	if got != want {
		t.Fatalf("empty layout = %q, want %q", got, want)
	}

	got, err = EncodeLayout(Layout{Material: "wood", Capacity: 5, Gap: 99, Segments: []Segment{{Code: "x", Span: 5}}})
	if err != nil {
		t.Fatalf("gap must not apply to one segment: %v", err)
	}
	want = "LAYOUT/1\n[base]\nmaterial=wood\ncapacity=5\n[segments]\nx:5\n[marks]\n[totals]\nused=5\nremaining=0\n"
	if got != want {
		t.Fatalf("single-segment layout = %q, want %q", got, want)
	}
}

func TestEncodeLayoutValidation(t *testing.T) {
	invalid := []Layout{
		{Material: "", Capacity: 1},
		{Material: "m", Capacity: -1},
		{Material: "m", Capacity: 1, Gap: -1},
		{Material: "m", Capacity: 1, Segments: []Segment{{Code: "", Span: 1}}},
		{Material: "m", Capacity: 1, Segments: []Segment{{Code: "x", Span: 0}}},
		{Material: "m", Capacity: 1, Segments: []Segment{{Code: "x", Span: -1}}},
		{Material: "m", Capacity: 1, Marks: []int{-1}},
		{Material: "m", Capacity: 1, Marks: []int{2}},
		{Material: "m", Capacity: 3, Gap: 1, Segments: []Segment{{Code: "x", Span: 2}, {Code: "y", Span: 1}}},
	}
	for i, layout := range invalid {
		if _, err := EncodeLayout(layout); err == nil {
			t.Errorf("case %d: expected error", i)
		}
	}
}

func TestEncodeLayoutArithmeticBoundaries(t *testing.T) {
	maxInt := int(^uint(0) >> 1)

	valid := Layout{Material: "m", Capacity: maxInt, Gap: maxInt, Segments: []Segment{{Code: "huge", Span: maxInt}}}
	got, err := EncodeLayout(valid)
	if err != nil {
		t.Fatalf("single maximum span was rejected: %v", err)
	}
	want := "LAYOUT/1\n[base]\nmaterial=m\ncapacity=" + strconv.Itoa(maxInt) + "\n[segments]\nhuge:" + strconv.Itoa(maxInt) + "\n[marks]\n[totals]\nused=" + strconv.Itoa(maxInt) + "\nremaining=0\n"
	if got != want {
		t.Fatalf("maximum-span output = %q, want %q", got, want)
	}

	invalid := []Layout{
		{Material: "m", Capacity: maxInt, Gap: 0, Segments: []Segment{{Code: "huge", Span: maxInt}, {Code: "one", Span: 1}}},
		{Material: "m", Capacity: maxInt, Gap: 1, Segments: []Segment{{Code: "huge", Span: maxInt}, {Code: "one", Span: 1}}},
		{Material: "m", Capacity: maxInt, Gap: maxInt, Segments: []Segment{{Code: "a", Span: 1}, {Code: "b", Span: 1}}},
	}
	for i, layout := range invalid {
		if _, err := EncodeLayout(layout); err == nil {
			t.Errorf("overflow/bounds case %d was accepted", i)
		}
	}
}

func TestEncodeLayoutInterpolatesTextWithoutMutatingIt(t *testing.T) {
	layout := Layout{Material: "m=raw", Capacity: 1, Segments: []Segment{{Code: "x:y", Span: 1}}}
	got, err := EncodeLayout(layout)
	if err != nil {
		t.Fatal(err)
	}
	want := "LAYOUT/1\n[base]\nmaterial=m=raw\ncapacity=1\n[segments]\nx:y:1\n[marks]\n[totals]\nused=1\nremaining=0\n"
	if got != want {
		t.Fatalf("raw text output = %q, want %q", got, want)
	}
}

