package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestSeverityConstantsAreIncreasing(t *testing.T) {
	if !(Debug < Info && Info < Warn && Warn < Error && Error < Fatal) {
		t.Fatalf("severity constants are not increasing: %v %v %v %v %v", Debug, Info, Warn, Error, Fatal)
	}
}

func TestParseSeverityWhitespaceAndASCIICase(t *testing.T) {
	cases := map[string]Severity{
		"debug": Debug,
		" DEBUG ": Debug,
		"\tInFo\n": Info,
		"wArN": Warn,
		"ERROR": Error,
		" Fatal\r": Fatal,
	}
	for input, want := range cases {
		got, err := ParseSeverity(input)
		if err != nil || got != want {
			t.Errorf("ParseSeverity(%q) = %v, %v; want %v", input, got, err, want)
		}
	}
}

func TestParseSeverityRejectsEverythingElse(t *testing.T) {
	for _, input := range []string{"", "   ", "warning", "err", "fatal!", "débug", "İNFO", "info level"} {
		if _, err := ParseSeverity(input); !errors.Is(err, ErrInvalidLevel) {
			t.Errorf("ParseSeverity(%q) error = %v, want ErrInvalidLevel", input, err)
		}
	}
}

func TestFilterLogsThresholdOrderDuplicatesAndFreshStorage(t *testing.T) {
	entries := []LogEntry{
		{Level: Debug, Message: "d"},
		{Level: Warn, Message: "same"},
		{Level: Error, Message: ""},
		{Level: Warn, Message: "same"},
		{Level: Fatal, Message: "f"},
	}
	before := append([]LogEntry(nil), entries...)
	got, err := FilterLogs(" WaRn ", entries)
	if err != nil {
		t.Fatal(err)
	}
	want := []LogEntry{entries[1], entries[2], entries[3], entries[4]}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
	if !reflect.DeepEqual(entries, before) {
		t.Fatal("input entries mutated")
	}
	got[0].Message = "changed"
	if entries[1].Message != "same" {
		t.Fatal("result aliases input storage")
	}
}

func TestFilterLogsEmptyResultIsNonNil(t *testing.T) {
	for _, entries := range [][]LogEntry{nil, {}, {{Level: Debug, Message: "x"}}} {
		got, err := FilterLogs("fatal", entries)
		if err != nil {
			t.Fatal(err)
		}
		if got == nil || len(got) != 0 {
			t.Fatalf("expected non-nil empty slice, got %#v", got)
		}
	}
}

func TestFilterLogsValidatesAllEntriesBeforeReturning(t *testing.T) {
	valid := func(level Severity) bool {
		return level == Debug || level == Info || level == Warn || level == Error || level == Fatal
	}
	var invalid Severity
	found := false
	for i := 0; i <= 5; i++ {
		candidate := Severity(i)
		if !valid(candidate) {
			invalid = candidate
			found = true
			break
		}
	}
	if !found {
		t.Fatal("could not select an invalid severity")
	}

	entries := []LogEntry{
		{Level: Fatal, Message: "would match"},
		{Level: invalid, Message: "invalid"},
		{Level: Error, Message: "later valid row"},
	}
	got, err := FilterLogs("debug", entries)
	if !errors.Is(err, ErrInvalidLevel) || got != nil {
		t.Fatalf("invalid entries returned %#v, %v; want nil and ErrInvalidLevel", got, err)
	}

	got, err = FilterLogs("bogus", []LogEntry{{Level: Fatal, Message: "x"}})
	if !errors.Is(err, ErrInvalidLevel) || got != nil {
		t.Fatalf("invalid minimum returned %#v, %v", got, err)
	}
	got, err = FilterLogs("İNFO", []LogEntry{{Level: Fatal, Message: "x"}})
	if !errors.Is(err, ErrInvalidLevel) || got != nil {
		t.Fatalf("non-ASCII minimum returned %#v, %v", got, err)
	}
}

