package solution

import (
	"reflect"
	"testing"
)

func strptr(v string) *string { return &v }
func i64ptr(v int64) *int64   { return &v }

func TestUpdateInventoryItemPartialAndCompleteUpdates(t *testing.T) {
	original := InventoryItem{Code: "A1", Name: "Old", CostCents: 10, Group: "g", Notes: "old note"}
	table := map[string]InventoryItem{"A1": original}

	got, err := UpdateInventoryItem(table, "A1", InventoryPatch{Notes: strptr("")})
	if err != nil {
		t.Fatal(err)
	}
	want := original
	want.Notes = ""
	if got != want || table["A1"] != want {
		t.Fatalf("notes-only update = %#v, stored %#v, want %#v", got, table["A1"], want)
	}

	name, group, notes := "New", " group two ", "note"
	cost := int64(0)
	got, err = UpdateInventoryItem(table, "A1", InventoryPatch{Name: &name, CostCents: &cost, Group: &group, Notes: &notes})
	if err != nil {
		t.Fatal(err)
	}
	want = InventoryItem{Code: "A1", Name: name, CostCents: 0, Group: group, Notes: notes}
	if got != want || table["A1"] != want {
		t.Fatalf("complete update = %#v, stored %#v, want %#v", got, table["A1"], want)
	}

	name, group, notes, cost = "later", "later", "later", 999
	if table["A1"] != want {
		t.Fatal("function retained patch pointers")
	}
}

func TestUpdateInventoryItemNilPatchIsSuccessfulNoOp(t *testing.T) {
	original := InventoryItem{Code: "x", Name: "n", CostCents: 1, Group: "g", Notes: "note"}
	table := map[string]InventoryItem{"x": original}
	got, err := UpdateInventoryItem(table, "x", InventoryPatch{})
	if err != nil || got != original || table["x"] != original {
		t.Fatalf("no-op patch = %#v, %v, stored %#v", got, err, table["x"])
	}
}

func TestUpdateInventoryItemValidatesWholePatchAtomically(t *testing.T) {
	original := InventoryItem{Code: "x", Name: "old", CostCents: 50, Group: "old-group", Notes: "old-note"}
	invalid := []InventoryPatch{
		{Name: strptr("")},
		{Name: strptr(" \t\n")},
		{Group: strptr("")},
		{Group: strptr(" \r\n")},
		{CostCents: i64ptr(-1)},
		{Name: strptr("valid"), CostCents: i64ptr(-1), Notes: strptr("new")},
		{Name: strptr("valid"), Group: strptr("  ")},
	}
	for i, patch := range invalid {
		table := map[string]InventoryItem{"x": original}
		got, err := UpdateInventoryItem(table, "x", patch)
		if err == nil {
			t.Errorf("case %d: expected error", i)
		}
		if got != original {
			t.Errorf("case %d: returned %#v, want original %#v", i, got, original)
		}
		if !reflect.DeepEqual(table, map[string]InventoryItem{"x": original}) {
			t.Errorf("case %d: table changed to %#v", i, table)
		}
	}
}

func TestUpdateInventoryItemMissingAndNilTables(t *testing.T) {
	original := InventoryItem{Code: "present", Name: "n", Group: "g"}
	for _, tc := range []struct {
		name  string
		table map[string]InventoryItem
		code  string
	}{
		{"nil table", nil, "x"},
		{"empty table", map[string]InventoryItem{}, "x"},
		{"missing", map[string]InventoryItem{"present": original}, "x"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			wasNil := tc.table == nil
			before := make(map[string]InventoryItem, len(tc.table))
			for k, v := range tc.table {
				before[k] = v
			}
			got, err := UpdateInventoryItem(tc.table, tc.code, InventoryPatch{Name: strptr("new")})
			if err == nil || got != (InventoryItem{}) {
				t.Fatalf("got %#v, %v; want zero value and error", got, err)
			}
			if wasNil {
				if tc.table != nil {
					t.Fatalf("nil table changed to %#v", tc.table)
				}
			} else if !reflect.DeepEqual(tc.table, before) {
				t.Fatalf("table mutated: %#v", tc.table)
			}
		})
	}
}

func TestUpdateInventoryItemEmptyCodeReturnsExistingOriginal(t *testing.T) {
	original := InventoryItem{Code: "stored-code", Name: "old", CostCents: 5, Group: "g", Notes: "note"}
	other := InventoryItem{Code: "other", Name: "other", Group: "g"}
	table := map[string]InventoryItem{"": original, "other": other}
	before := map[string]InventoryItem{"": original, "other": other}
	got, err := UpdateInventoryItem(table, "", InventoryPatch{Name: strptr("new"), Notes: strptr("")})
	if err == nil || got != original {
		t.Fatalf("got %#v, %v; want exact existing original and error", got, err)
	}
	if !reflect.DeepEqual(table, before) {
		t.Fatalf("table mutated: %#v", table)
	}
}

func TestUpdateInventoryItemUsesLookupKeyWithoutRewritingCode(t *testing.T) {
	original := InventoryItem{Code: "key-code", Name: "n", CostCents: 5, Group: "g"}
	table := map[string]InventoryItem{"lookup": original}

	got, err := UpdateInventoryItem(table, "lookup", InventoryPatch{Notes: strptr("updated")})
	want := original
	want.Notes = "updated"
	if err != nil || got != want || table["lookup"] != want {
		t.Fatalf("successful mismatched-key update = %#v, %v, stored %#v", got, err, table["lookup"])
	}

	got, err = UpdateInventoryItem(table, "lookup", InventoryPatch{CostCents: i64ptr(-1)})
	if err == nil || got != want || table["lookup"] != want {
		t.Fatalf("invalid update = %#v, %v, stored %#v", got, err, table["lookup"])
	}
}

